const D = { gap:.5, thickness:.5, energy:.6, speed:1, hue:130, curvature:.5, glow:.5, flicker:.4, scale:1, density:.5, x:.5, y:.5, style:'crt', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, frc=v=>v-Math.floor(v), clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const style=P.style;
const en=clp(P.energy,0,1)*(.5+.6*K.intensity);
const gap=clp(P.gap,0,1), thick=clp(P.thickness,0,1);
const eh=md(P.hue,360);
const period=Math.max(2, Math.round(u*(0.004+gap*0.02)));
const lineH=Math.max(1, Math.round(period*(0.35+thick*0.5)));
const curv=clp(P.curvature,0,1);

// cached overlay buffer (mask + barrel + sheen), rebuilt only on size/style/param bucket change
const key=W+'x'+Hh+'|'+style+'|'+period+'_'+lineH+'|'+P.seed+'|'+Math.round(curv*4)+'|'+Math.round(eh/20);
if(S.key!==key){
  S.key=key;
  const g=createGraphics(W,Hh); g.colorMode(g.HSB,360,100,100,100); g.clear(); g.noStroke();
  const gc=g.drawingContext;
  if(style==='trinitron'){
    // vertical aperture grille — bright RGB bars, dark separators (composited MULTIPLY)
    const cw=Math.max(3,period);
    for(let x=0;x<W;x+=cw){
      const ch=Math.floor(x/cw)%3, hh=ch===0?0:ch===1?120:240;
      g.fill(hh,70,100,100); g.rect(x,0,cw*0.82,Hh);
      g.fill(0,0,0,100); g.rect(x+cw*0.82,0,cw*0.18,Hh);
    }
    g.fill(0,0,0,45); for(let y=0;y<Hh;y+=Math.max(3,period)) g.rect(0,y,W,Math.max(1,lineH*0.5));
  } else if(style==='shadowmask'){
    // RGB dot triad grid on black — emissive mask look under MULTIPLY
    const cw=Math.max(3,period*1.1);
    g.fill(0,0,0,100); g.rect(0,0,W,Hh);
    for(let y=0;y<Hh;y+=cw){
      const off=(Math.floor(y/cw)%2)*cw*0.5;
      for(let x=0;x<W;x+=cw){
        const ch=Math.floor(x/cw)%3, hh=ch===0?0:ch===1?120:240;
        g.fill(hh,70,100,100); g.ellipse(x+off+cw*0.5,y+cw*0.5,cw*0.56,cw*0.56);
      }
    }
  } else {
    // crt / vhs — translucent horizontal scanlines
    g.fill(0,0,0, 28+thick*42);
    for(let y=0;y<Hh;y+=period) g.rect(0,y,W,lineH);
    if(style==='crt'){ g.fill(eh,55,100,5); for(let y=lineH;y<Hh;y+=period) g.rect(0,y,W,Math.max(1,period-lineH)); }
  }
  // barrel corner darkening (all styles)
  const rr=Math.max(W,Hh)*0.78;
  const bg=gc.createRadialGradient(W/2,Hh/2,rr*(0.42+(1-curv)*0.32),W/2,Hh/2,rr*1.06);
  bg.addColorStop(0,'rgba(0,0,0,0)'); bg.addColorStop(1,`rgba(0,0,0,${(0.22+curv*0.46).toFixed(3)})`);
  gc.globalCompositeOperation='source-over'; gc.fillStyle=bg; gc.fillRect(0,0,W,Hh);
  // glass specular sheen (upper-left)
  const sg=gc.createRadialGradient(W*0.3,Hh*0.22,0,W*0.3,Hh*0.22,u*0.55);
  sg.addColorStop(0,'rgba(255,255,255,0.06)'); sg.addColorStop(1,'rgba(255,255,255,0)');
  gc.globalCompositeOperation='lighter'; gc.fillStyle=sg; gc.fillRect(0,0,W,Hh);
  gc.globalCompositeOperation='source-over';
  S.scan=g;
}

noStroke();
blendMode(MULTIPLY);
image(S.scan,0,0);
blendMode(BLEND);

// --- live: rolling refresh bands (motion floor — two speeds so they never realign at 8s) ---
const dc=drawingContext, oldOp=dc.globalCompositeOperation;
const glow=clp(P.glow,0,1);
const span=Hh+u*0.3;
const flick=1 + (A.treble*0.4 + (fr(Math.floor(K.t*22))-0.5)*0.5)*clp(P.flicker,0,1)*en;
dc.globalCompositeOperation='lighter';
[[0.19,0.0,0.10],[0.115,0.5,0.07]].forEach((b,bi)=>{
  const v=u*b[0]*(0.4+P.speed);
  const by=md(K.t*v + b[1]*span, span)-u*0.15;
  const bh=u*b[2]*(0.9+0.3*Math.sin(K.t*0.4+bi));
  const lg=dc.createLinearGradient(0,by-bh,0,by+bh);
  const ba=clp((0.05+0.13*glow)*flick*(bi?0.6:1),0,0.28);
  lg.addColorStop(0,'rgba(255,255,255,0)');
  lg.addColorStop(0.5,`rgba(255,255,255,${ba.toFixed(3)})`);
  lg.addColorStop(1,'rgba(255,255,255,0)');
  dc.fillStyle=lg; dc.fillRect(0,by-bh,W,bh*2);
});
dc.globalCompositeOperation=oldOp;

// --- vhs: jittering tracking tear + chroma bleed + dropouts ---
if(style==='vhs'){
  const ty=md(K.t*u*0.05 + Math.sin(K.t*2.0)*u*0.12, Hh);
  const th=u*(0.02+0.03*Math.abs(Math.sin(K.t*0.7)));
  blendMode(SCREEN); noStroke();
  fill(0,0,100, 8+16*en); rect(0,ty,W,th);
  fill(md(eh+170,360),80,100,10*en); rect(u*0.01,ty,W,th*0.5);
  fill(md(eh+300,360),80,100,10*en); rect(-u*0.01,ty+th*0.5,W,th*0.5);
  const nn=Math.round(5+9*clp(P.density,0,1));
  fill(0,0,100,18*en);
  for(let i=0;i<nn;i++){ const fs=i+Math.floor(K.t*15); const nx=fr(fs*1.7)*W, ny=fr(fs*2.3)*Hh, nw=u*0.02+fr(fs*3.1)*u*0.06; rect(nx,ny,nw,Math.max(1,period*0.6)); }
  blendMode(BLEND);
}

blendMode(BLEND); dc.globalCompositeOperation=oldOp; dc.shadowBlur=0; noStroke();
